// ============================================================
// DADOS DA PLATAFORMA — Comunicação Interpessoal
// (quiz, flashcards, preenchimento, história, fofoca)
// ============================================================

// ============================================================
// DATA: 100 QUIZ QUESTIONS
// ============================================================
const quizData = [
  {q:"O que é a Comunicação Interpessoal?",o:["Envio de mensagens em massa","Troca de informação e significado entre duas ou mais pessoas","Comunicação através de tecnologia","Leitura de documentos oficiais"],a:1,e:"A Comunicação Interpessoal envolve a troca de informação, significado e emoções entre pessoas, sendo inseparável das relações humanas."},
  {q:"Segundo Minter (2010), qual é a relação entre comunicação e relações humanas?",o:["São conceitos opostos","São quase sinónimos e extremamente ligados","A comunicação é mais importante","As relações humanas dispensam comunicação"],a:1,e:"Minter (2010) afirma que os conceitos são 'quase sinónimos' e que é impossível haver relações humanas sem comunicação e vice-versa."},
  {q:"O que são os 'sinais não-verbais' na comunicação?",o:["Palavras escritas","Mensagens transmitidas sem palavras faladas (gestos, expressões, postura, toque)","Apenas o silêncio","Apenas contacto visual"],a:1,e:"Os sinais não-verbais incluem gestos, expressões faciais, postura corporal, toque, tom de voz e uso do espaço — tudo o que comunica sem palavras."},
  {q:"Qual é a Teoria da Gestão da Informação Motivada (TGIM)?",o:["Teoria sobre gestão de empresas","Teoria sobre como as pessoas gerem a incerteza e ansiedade em situações de comunicação","Teoria sobre tecnologia de informação","Teoria sobre motivação no trabalho"],a:1,e:"A TGIM explica como as pessoas gerem a incerteza e ansiedade ao comunicar, buscando informação para reduzir a incerteza."},
  {q:"O que é a Teoria dos Objetivos Múltiplos?",o:["Teoria sobre múltiplas tarefas","Teoria que explica como as pessoas perseguem vários objetivos em simultâneo na comunicação","Teoria sobre objetivos desportivos","Teoria sobre gestão de projetos"],a:1,e:"A Teoria dos Objetivos Múltiplos mostra que ao comunicar perseguimos vários objetivos em simultâneo: instrumentais, relacionais e identitários."},
  {q:"O que é o 'Perfil Verbal-Não Verbal Discrepante'?",o:["Quando se fala muito alto","Quando a mensagem verbal e não-verbal são inconsistentes/contraditórias","Quando não se usa gestos","Quando se fala e escreve ao mesmo tempo"],a:1,e:"O Perfil Discrepante ocorre quando o que dizemos verbalmente contradiz o que a nossa linguagem corporal e tom de voz transmitem."},
  {q:"O que é a Troca Social na comunicação interpessoal?",o:["Troca de dinheiro entre pessoas","Princípio de que as interações humanas envolvem trocas de recursos, recompensas e custos","Troca de redes sociais","Troca de presentes"],a:1,e:"A Troca Social é o princípio segundo o qual as interações humanas são governadas por trocas de recursos, custos e recompensas, orientadas pelo interesse próprio e reciprocidade."},
  {q:"O que distingue uma Troca Social de uma Troca Económica?",o:["A troca social envolve dinheiro, a económica não","A troca económica tem obrigações legais e precisão; a social é voluntária e baseada em confiança","São exatamente iguais","A troca social é mais formal"],a:1,e:"A troca económica envolve obrigações legais e precisão (ex: preço fixo). A troca social é voluntária, baseada em confiança, com custos e recompensas mais flexíveis."},
  {q:"O que é o Interacionismo Simbólico?",o:["Uso de símbolos matemáticos","Perspetiva que vê o comportamento social como resultado do significado que as pessoas atribuem aos símbolos","Teoria sobre sinais de trânsito","Estudo de logos e marcas"],a:1,e:"O Interacionismo Simbólico vê o comportamento social como produto dos significados simbólicos que as pessoas constroem nas interações."},
  {q:"O que afirma o Teorema de Thomas?",o:["Que a realidade é objetiva","'Se as pessoas definem as situações como reais, elas são reais nas suas consequências'","Que os símbolos são naturais","Que a comunicação é linear"],a:1,e:"O Teorema de Thomas diz que se as pessoas definem uma situação como real, ela torna-se real nas suas consequências — mostrando o poder das perceções."},
  {q:"Qual a diferença entre Ouvir e Escutar?",o:["Não há diferença","Ouvir é passivo (receção de som); Escutar é ativo (processar, interpretar e responder ao que se ouve)","Escutar é apenas para música","Ouvir requer mais esforço"],a:1,e:"Ouvir é um processo fisiológico passivo. Escutar implica atenção ativa, compreensão e resposta — é um processo cognitivo e emocional."},
  {q:"O que é a Escuta Ativa?",o:["Ouvir música com atenção","Forma de escuta em que o receptor demonstra atenção, compreensão e interesse ativo na mensagem do outro","Apenas responder com perguntas","Tomar notas durante uma conversa"],a:1,e:"A Escuta Ativa envolve prestar atenção plena, mostrar envolvimento, pedir clarificações e dar feedback — demonstrando que o outro foi compreendido."},
  {q:"O que é a Escuta Empática?",o:["Escutar apenas factos","Escutar procurando compreender os sentimentos e perspetiva do outro","Escutar para contradizer","Apenas escutar quando é obrigatório"],a:1,e:"A Escuta Empática vai além dos factos — tenta compreender a perspetiva emocional do outro, colocando-se no seu lugar."},
  {q:"Qual é uma barreira psicológica à comunicação?",o:["Ruído ambiental","Preconceitos, emoções fortes ou experiências passadas que distorcem a receção da mensagem","Falha de microfone","Língua diferente"],a:1,e:"As barreiras psicológicas incluem preconceitos, expectativas, emoções e experiências passadas que interferem na interpretação da mensagem."},
  {q:"Qual é uma barreira semântica à comunicação?",o:["Falar muito alto","Diferenças no significado atribuído às palavras ou símbolos entre emissor e recetor","Falta de iluminação","Excesso de barulho"],a:1,e:"As barreiras semânticas surgem quando os interlocutores atribuem significados diferentes às mesmas palavras, expressões ou conceitos."},
  {q:"O que é a Inteligência Emocional (IE)?",o:["A capacidade de fazer cálculos complexos","A capacidade de reconhecer, compreender e gerir as próprias emoções e as dos outros","Inteligência académica","A capacidade de reprimir emoções"],a:1,e:"A IE é a capacidade de perceber, usar, compreender e regular as emoções — tanto as próprias como as dos outros — envolvendo autoconsciência, autorregulação, motivação, empatia e competências sociais."},
  {q:"Quais são os 5 pilares da Inteligência Emocional segundo Goleman?",o:["Força, velocidade, resistência, flexibilidade, equilíbrio","Autoconsciência, autorregulação, motivação, empatia e competências sociais","Lógica, criatividade, memória, atenção, linguagem","Assertividade, passividade, agressividade, empatia, silêncio"],a:1,e:"Os 5 pilares de Goleman são: autoconsciência (conhecer as próprias emoções), autorregulação, motivação interna, empatia e competências sociais."},
  {q:"O que é a IE de 'habilidade' (ability)?",o:["A capacidade de realizar tarefas manuais","Um conjunto de capacidades cognitivas sobre emoções: perceber, usar, compreender e regular emoções","A tendência para expressar emoções","A capacidade de ignorar emoções"],a:1,e:"A IE de habilidade envolve capacidades cognitivas mensuráveis: perceber emoções nos outros, usá-las para pensar, compreendê-las e regulá-las adaptativamente."},
  {q:"O que é a IE de 'traço' (trait)?",o:["Um traço físico observável","Traços auto-reportados relacionados com autoeficácia emocional, bem-estar e sociabilidade","A habilidade de calcular emoções","Traços exclusivamente genéticos"],a:1,e:"A IE de traço refere-se a como a pessoa percebe as suas próprias características emocionais — é auto-reportada e inclui bem-estar subjetivo e autoeficácia emocional."},
  {q:"O que é a Teoria da Atribuição no contexto da IE?",o:["Teoria sobre atribuição de tarefas no trabalho","Processo pelo qual interpretamos as causas do comportamento dos outros (interno vs externo)","Teoria sobre distribuição de recursos","Processo de atribuição de notas"],a:1,e:"A Teoria da Atribuição explica como interpretamos as causas do comportamento alheio — atribuindo causas internas (personalidade) ou externas (situação), o que afeta como comunicamos."},
  {q:"O que é a Teoria da Troca Afetiva?",o:["Troca de presentes em relações afetivas","Como as emoções trocadas nas interações influenciam e regulam as relações interpessoais","Teoria sobre mercados emocionais","Troca de informação racional"],a:1,e:"A Teoria da Troca Afetiva explica como as emoções que transmitimos e recebemos nas interações moldam e regulam a qualidade das nossas relações."},
  {q:"Como se caracteriza o estilo de comunicação Assertivo?",o:["Impõe a sua vontade ignorando os outros","Expressa necessidades e opiniões com respeito pelos direitos próprios e dos outros","Evita sempre o conflito","Usa ironia e sarcasmo para comunicar"],a:1,e:"O assertivo defende os seus direitos construtivamente, é direto, honesto e específico, e respeita os direitos dos outros — o estilo mais adaptativo."},
  {q:"Como se caracteriza o estilo de comunicação Passivo?",o:["Expressa as suas opiniões com confiança","Evita o conflito, sublima as suas necessidades e cede facilmente quando desafiado","Impõe as suas necessidades","Usa manipulação indireta"],a:1,e:"O passivo evita conflito, teme a desaprovação, hesita antes de responder e suprime as suas necessidades para satisfazer os outros."},
  {q:"Como se caracteriza o estilo de comunicação Agressivo?",o:["Respeita as opiniões dos outros","Procura alcançar objetivos atacando, ameaçando ou intimidando os outros","Evita confrontos a todo o custo","Comunica de forma indireta"],a:1,e:"O agressivo procura os seus objetivos às custas dos outros, usa ameaças, ataques pessoais, é sarcástico e não coopera — 'eu venço, tu perdes'."},
  {q:"O que distingue o estilo Passivo-Agressivo?",o:["Combina agressividade física com passividade verbal","Evita confronto direto mas manifesta insatisfação de forma indireta (ironia, sabotagem velada)","É uma versão moderada do assertivo","É o estilo mais eficaz"],a:1,e:"O passivo-agressivo evita o confronto direto mas expressa insatisfação indiretamente através de ironia, ambiguidade ou sabotagem velada."},
  {q:"Porque é o estilo assertivo considerado o mais desejável?",o:["Porque garante sempre ganhar conflitos","Porque equilibra defesa dos próprios direitos com respeito pelos outros, contribuindo para relações saudáveis","Porque é o mais passivo","Porque nunca cria conflito"],a:1,e:"A assertividade é desejável porque defende os direitos próprios sem violar os dos outros, promove comunicação aberta e contribui para maior satisfação pessoal e relacional."},
  {q:"O que é o Modelo DESC na comunicação assertiva?",o:["Modelo de defesa, escuta, síntese e conclusão","Estrutura: Descreve → Expressa → Sugere → Consequências — para comunicar assertivamente em situações de conflito","Modelo de desenvolvimento estratégico de competências","Modelo de decisão empresarial"],a:1,e:"O DESC é uma estrutura para comunicação assertiva: Descreve o comportamento problemático, Expressa como te sentes, Sugere uma mudança, e indica as Consequências positivas."},
  {q:"O que é o Modelo XYZ?",o:["Modelo matemático","Estrutura de comunicação: 'Quando X, sinto Y, porque Z' — para expressar sentimentos de forma não acusatória","Modelo de gestão de projetos","Modelo de análise de dados"],a:1,e:"O Modelo XYZ permite expressar sentimentos sem atacar o outro: 'Quando fazes X, sinto Y, porque Z' — foca no comportamento e não na pessoa."},
  {q:"O que é a Teoria da Retórica Normativa (TRN)?",o:["Teoria sobre normas gramaticais","Teoria que estuda os princípios éticos da persuasão na comunicação","Teoria sobre retórica política","Teoria sobre normas de pronunciação"],a:1,e:"A TRN, baseada em Aristóteles, estuda os princípios éticos da persuasão — como comunicar de forma eficaz e justa, respeitando o receptor."},
  {q:"O que é o Ethos na retórica?",o:["Apelo às emoções do público","Credibilidade e integridade do comunicador que leva o público a confiar na mensagem","Uso de argumentos lógicos","Estrutura do discurso"],a:1,e:"Ethos é a credibilidade do orador — a perceção de integridade, competência e confiabilidade que leva o público a aceitar a mensagem."},
  {q:"O que é o Logos na retórica?",o:["Apelo emocional","Uso de argumentos racionais, lógicos e evidências para convencer","A credibilidade do orador","A narrativa pessoal do orador"],a:1,e:"Logos refere-se ao uso de argumentos racionais, dados, provas e lógica para persuadir — o apelo à razão do público."},
  {q:"O que é o Pathos na retórica?",o:["A credibilidade do orador","Apelo às emoções do público para envolver e persuadir","Uso de dados estatísticos","A estrutura lógica do argumento"],a:1,e:"Pathos é o apelo emocional — ativar as emoções do público (medo, esperança, empatia) para tornar a mensagem mais persuasiva."},
  {q:"Segundo a TRN, como deve ser usado o Pathos eticamente?",o:["Pode manipular livremente as emoções","Deve ser usado respeitando a capacidade crítica do público, sem manipulação emocional","Deve ser evitado completamente","Deve ser usado apenas em discursos políticos"],a:1,e:"A TRN defende que o apelo emocional deve ser ético — pode envolver emoções mas não deve manipular, distorcer ou explorar vulnerabilidades do público."},
  {q:"O que são os 'relacionamentos' segundo Watzlawick?",o:["Apenas amizades formais","Emergem da interação entre pessoas com regras estabelecidas e aceites por ambas as partes","Contratos legais entre pessoas","Apenas relações familiares"],a:1,e:"Para Watzlawick, os relacionamentos emergem da interação com regras comunicativas aceites por ambas as partes, regulando os comportamentos."},
  {q:"O que é a 'Expressividade' na comunicação não-verbal?",o:["Volume da voz","Grau de abertura e visibilidade das emoções que o comunicador projeta através de sinais não-verbais","Habilidade de escrever expressivamente","Uso de palavras expressivas"],a:1,e:"A Expressividade é a intensidade com que as emoções são projetadas através de sinais não-verbais — movimentos, microexpressões, tom de voz."},
  {q:"O que é a 'Capacidade de Resposta' na comunicação?",o:["Velocidade de digitação","Habilidade de perceber e responder adequadamente às necessidades e sinais comunicativos do interlocutor","Capacidade de falar alto","Tempo de resposta a e-mails"],a:1,e:"A Capacidade de Resposta é a habilidade de 'ler' os sinais do outro e ajustar a própria comunicação de forma adaptativa e oportuna."},
  {q:"Por que são importantes os silêncios na comunicação interpessoal?",o:["Porque significam falta de interesse","São elementos fundamentais que fazem parte da comunicação, criam espaço para escuta e transmitem emoções","Devem ser sempre evitados","São apenas pausas sem significado"],a:1,e:"Os silêncios são fundamentais: fazem parte integrante da comunicação, são muito frequentes, podem ser embaraçosos ou profundos, e são necessários para escutar o outro."},
  {q:"O que é a 'interdependência' nas relações interpessoais?",o:["Dependência financeira","Os resultados de cada pessoa são influenciados pelos esforços dos outros — os resultados são partilhados","Independência total entre pessoas","Dependência emocional"],a:1,e:"Interdependência significa que numa relação os resultados de cada um são influenciados pelo outro — o sucesso individual depende dos esforços do parceiro."},
  {q:"O que é a 'equidade' nas trocas sociais?",o:["Igualdade absoluta de recursos","Perceção de que os custos e benefícios são distribuídos de forma justa na relação","Ausência de conflito","Partilha igual de responsabilidades"],a:1,e:"A equidade é a perceção de justiça na distribuição de custos e benefícios numa relação — não significa igualdade perfeita mas proporcionalidade percebida."},
  {q:"O que é a 'reciprocidade' na troca social?",o:["Dar sempre o mesmo que se recebe em dinheiro","Princípio de que as trocas devem ser mutuamente benéficas e que as ações dos outros geram expectativas de retorno","Evitar qualquer troca","Apenas troca de favores formais"],a:1,e:"A reciprocidade é o princípio de que as trocas nas relações devem ter retorno — quando alguém nos dá algo, sentimos necessidade de retribuir."},
  {q:"O que é o 'interesse próprio' (self-interest) na troca social?",o:["Egoísmo puro","O ímpeto pelo qual as pessoas agem de acordo com os seus resultados percebidos e projetados nas interações","Apenas motivações financeiras","Comportamento altruísta"],a:1,e:"O interesse próprio é a motivação para agir de acordo com os resultados esperados de cada interação — não é necessariamente egoísta, pois pode incluir cooperação."},
  {q:"Qual é a definição de assertividade segundo Alberti & Emmons (2017)?",o:["Impor a vontade sobre os outros","Expressão direta, honesta e respeitosa de pensamentos e sentimentos","Evitar conflito a todo o custo","Usar persuasão intensa"],a:1,e:"Alberti & Emmons definem assertividade como 'expressão direta, honesta e respeitosa de pensamentos e sentimentos', equilibrando auto-expressão com respeito pelo outro."},
  {q:"Quais são os benefícios da assertividade segundo a investigação?",o:["Aumento de conflitos","Relações equilibradas, redução de stress e maior capacidade de resolução de problemas","Isolamento social","Maior dominância nas relações"],a:1,e:"Estudos mostram que a assertividade está ligada a relações mais equilibradas, menor stress, maior satisfação profissional e melhor resolução de conflitos (Speed et al., 2018)."},
  {q:"O que é a IE 'mista' (competências)?",o:["Combinação de IE de habilidade e de traço","Competências comportamentais aplicadas ao desempenho social (consciência de si, autorregulação, motivação, empatia, competências sociais)","Um tipo de IE indefinido","IE que combina emoções e lógica"],a:1,e:"A IE mista refere-se a competências emocionais comportamentais observáveis — como dar feedback, gerir conflitos ou demonstrar empatia em contextos sociais e profissionais."},
  {q:"Como a IE de habilidade afeta a comunicação?",o:["Não afeta a comunicação","Melhora a precisão ao descodificar expressões e voz, e melhora o 'timing' comunicativo","Aumenta a agressividade","Reduz a necessidade de comunicar"],a:1,e:"A IE de habilidade permite ler com mais precisão as expressões faciais e tom de voz dos outros, e ter melhor 'timing' — saber quando e como dizer as coisas."},
  {q:"O que é a 'autoconsciência' como pilar da IE?",o:["Saber fazer auto-retratos","A capacidade de reconhecer e compreender as próprias emoções, forças e limitações","Vigilância constante dos outros","Consciência do ambiente físico"],a:1,e:"A autoconsciência é o primeiro pilar da IE de Goleman — a capacidade de reconhecer as próprias emoções no momento em que ocorrem e compreender como afetam o comportamento."},
  {q:"O que é a 'autorregulação' como pilar da IE?",o:["Disciplina física","A capacidade de controlar emoções destrutivas e impulsos, e adaptar-se a circunstâncias em mudança","Regulação de temperatura corporal","Autocontrolo alimentar"],a:1,e:"A autorregulação é a capacidade de gerir as próprias emoções e impulsos — não os suprimir, mas expressá-los de forma adequada e adaptativa."},
  {q:"O que é a 'empatia' como pilar da IE?",o:["Simpatia superficial","A capacidade de compreender as emoções dos outros e responder de forma adequada","Leitura do pensamento","Imitação das emoções dos outros"],a:1,e:"A empatia é a capacidade de perceber e compreender os sentimentos e perspetivas dos outros — colocarmo-nos no lugar deles para responder adequadamente."},
  {q:"Que tipo de comportamento não-verbal caracteriza o comunicador assertivo?",o:["Olhar desafiante e gestos ameaçadores","Voz firme e calma, contacto visual sem intimidar, expressão facial aberta e postura descontraída","Desviar o olhar, fala fraca e hesitante","Interrupções frequentes e tom agressivo"],a:1,e:"O assertivo tem voz firme mas calma, mantém contacto visual sem intimidar, tem expressão facial aberta e postura descontraída — transmite confiança sem agressividade."},
  {q:"Que tipo de comportamento não-verbal caracteriza o comunicador passivo?",o:["Postura dominante e voz forte","Desvia o olhar, postura retraída, voz fraca ou lamurienta, sorriso forçado","Expressão facial agressiva","Interrompe frequentemente"],a:1,e:"O passivo desvia o olhar, tem postura retraída, fala com voz fraca ou hesitante e sorri de forma forçada — sinais de insegurança e submissão."},
  {q:"O que é a 'Teoria da Retórica Normativa' especificamente?",o:["Uma teoria sobre gramática normativa","Uma teoria que combina princípios clássicos de persuasão com ética comunicativa","Uma teoria sobre leis de comunicação","Uma teoria sobre normas sociais"],a:1,e:"A TRN combina os princípios clássicos de Aristóteles com preocupações éticas modernas — como persuadir de forma eficaz, honesta e respeitosa."},
  {q:"Que papel tem a 'credibilidade' na persuasão eficaz?",o:["Não é relevante para a persuasão","O público confia mais em comunicadores que percebe como credíveis e íntegros (Ethos)","Só é relevante em contextos académicos","A credibilidade pode ser fabricada facilmente"],a:1,e:"A credibilidade (Ethos) é fundamental — quando o público percebe o comunicador como competente e honesto, está mais disposto a aceitar a mensagem."},
  {q:"O que é a 'comunicação contemporânea' e os seus desafios?",o:["Comunicação por carta","Comunicação na era digital — marcada por excesso de informação, velocidade, filtros algorítmicos e questões de autenticidade","Comunicação apenas face a face","Comunicação sem tecnologia"],a:1,e:"A comunicação contemporânea enfrenta desafios como sobrecarga informacional, velocidade das interações digitais, questões de autenticidade e influência do contexto cultural."},
  {q:"O que é a 'autenticidade' na comunicação contemporânea?",o:["Dizer sempre o que pensamos sem filtros","A correspondência genuína entre o que se sente interiormente e o que se expressa — comunicar de forma verdadeira","Comunicar apenas factos verificáveis","Evitar qualquer tipo de persuasão"],a:1,e:"A autenticidade é a congruência entre o estado interno e a expressão externa — comunicar de forma genuína, sem máscaras ou performatividade excessiva."},
  {q:"Como a Cultura afeta a Comunicação Interpessoal?",o:["Não tem qualquer influência","Molda os padrões de comunicação, os valores, as normas de proximidade, de contacto visual e de expressão emocional","Apenas afeta a língua falada","Afeta apenas a comunicação formal"],a:1,e:"A cultura influencia profundamente como comunicamos — desde regras de contacto visual e toque, ao estilo de negociação, à expressão de emoções e ao uso do silêncio."},
  {q:"O que é a 'motivação' como pilar da IE de Goleman?",o:["Motivação financeira","Impulso interno para alcançar objetivos com entusiasmo e persistência, independentemente de recompensas externas","Motivação dada por outros","Motivação para evitar emoções"],a:1,e:"A motivação intrínseca é a paixão interna pelo trabalho — não movida por dinheiro ou status, mas por satisfação e crescimento pessoal — um pilar da IE de Goleman."},
  {q:"O que é a 'competência social' como pilar da IE?",o:["Habilidade de trabalhar sozinho","Capacidade de gerir relações, inspirar e influenciar os outros e construir redes de contacto","Habilidade de memorizar nomes","Competência técnica"],a:1,e:"A competência social é a capacidade de gerir relações interpessoais com eficácia — persuadir, liderar, construir redes e gerir conflitos construtivamente."},
  {q:"Porque é que 'é impossível não comunicar' (Watzlawick)?",o:["Porque todos falam constantemente","Porque mesmo o silêncio e a inação transmitem mensagens nas relações interpessoais","Porque a comunicação é automática","Porque os humanos comunicam 24h por dia"],a:1,e:"Watzlawick afirma que 'é impossível não comunicar' — mesmo o silêncio, a ausência ou a inação são formas de mensagem nas interações interpessoais."},
  {q:"O que são as 'Competências Sociais' no contexto da IE?",o:["Etiqueta social formal","Conjunto de habilidades para gerir relações com eficácia: comunicação, liderança, resolução de conflitos, trabalho em equipa","Apenas habilidades de networking","Capacidade de memorizar nomes"],a:1,e:"As competências sociais da IE incluem habilidades relacionais: comunicar com clareza, liderar, inspirar mudança, gerir conflitos e construir equipas colaborativas."},
  {q:"Qual é o objetivo do Modelo DESC?",o:["Descrever emoções de forma vaga","Estruturar a comunicação assertiva para resolver conflitos de forma construtiva, sem atacar a pessoa","Evitar conversas difíceis","Impor soluções aos outros"],a:1,e:"O DESC oferece uma estrutura para abordar situações difíceis de forma assertiva: descrevendo o comportamento, expressando sentimentos, sugerindo mudança e mostrando as consequências."},
  {q:"Qual é a diferença entre 'comunicação de alta contexto' e 'baixo contexto'?",o:["Alta contexto usa mais tecnologia","Alta contexto usa muito contexto implícito (cultura asiática); baixo contexto é mais direto e explícito (cultura ocidental)","Não há diferença real","Alta contexto é mais ruidosa"],a:1,e:"Culturas de alto contexto (ex: japonesa) comunicam muito através de contexto implícito, relações e não-verbal. Culturas de baixo contexto (ex: americana) são mais diretas e explícitas."},
  {q:"O que são as 'barreiras fisiológicas/ambientais' à comunicação?",o:["Preconceitos pessoais","Obstáculos físicos como ruído, temperatura, distância, ou limitações sensoriais do receptor","Diferenças de idioma","Emoções negativas"],a:1,e:"As barreiras fisiológicas incluem surdez, fadiga, dor; as ambientais incluem ruído, iluminação inadequada, distância ou distrações físicas no ambiente."},
  {q:"O que é a 'Escuta Reflexiva'?",o:["Escutar enquanto se olha ao espelho","Técnica de escuta em que se reformula e reflete de volta o que o outro disse para confirmar compreensão","Escutar de forma passiva","Escutar apenas factos objetivos"],a:1,e:"A escuta reflexiva envolve parafrasear ou reformular o que o outro disse — 'Então o que estás a dizer é...' — para confirmar compreensão e mostrar atenção."},
  {q:"Como os 'preconceitos' afetam a escuta?",o:["Não têm impacto na escuta","Filtram e distorcem a mensagem recebida — ouvimos o que esperamos ouvir e ignoramos o que contraria as nossas crenças","Melhoram a compreensão","Só afetam a comunicação escrita"],a:1,e:"Os preconceitos são barreiras psicológicas que fazem com que filtremos as mensagens — tendemos a ouvir o que confirma as nossas crenças (confirmação cognitiva)."},
  {q:"Qual é a função do 'feedback' na comunicação interpessoal?",o:["Avaliar o desempenho académico","Resposta do recetor que informa o emissor sobre como a mensagem foi recebida e compreendida","Apenas criticar o comunicador","Finalizar a conversa"],a:1,e:"O feedback é a resposta do recetor que fecha o ciclo comunicativo — informa o emissor se a mensagem foi recebida, compreendida e que efeito produziu."},
  {q:"O que é a 'proxémica' na comunicação não-verbal?",o:["Estudo de expressões faciais","Estudo do uso e perceção do espaço físico nas interações (distância íntima, pessoal, social, pública)","Estudo do toque","Estudo do olhar"],a:1,e:"A proxémica (Hall) estuda como usamos o espaço nas interações — distância íntima (~45cm), pessoal (~120cm), social (~360cm) e pública (+360cm)."},
  {q:"O que é a 'cinésica' na comunicação não-verbal?",o:["Estudo do espaço","Estudo dos movimentos corporais — gestos, postura, expressões faciais, contacto visual","Estudo do tempo","Estudo da voz"],a:1,e:"A cinésica (Birdwhistell) é o estudo dos movimentos corporais como forma de comunicação — gestos, postura, expressões faciais, olhar e orientação do corpo."},
  {q:"O que é a 'paralinguagem' na comunicação?",o:["Idioma paralelo","Elementos vocais que acompanham as palavras: tom, ritmo, volume, pausas, entonação, timbre","Linguagem de sinais","Segunda língua aprendida"],a:1,e:"A paralinguagem são os elementos vocais além das palavras — como dizemos algo: tom, volume, ritmo, pausas e entonação que modificam o significado da mensagem."},
  {q:"Qual é a importância do 'toque' nas relações interpessoais?",o:["Não tem importância","É através do contacto físico que se transmitem sentimentos e se desencadeiam reações positivas ou negativas","Deve ser sempre evitado","Só é relevante em relações românticas"],a:1,e:"O toque é uma forma poderosa de comunicação não-verbal — transmite afeto, apoio, poder ou dominância, e desencadeia reações emocionais fortes."},
  {q:"Como o 'tempo' funciona como forma de comunicação?",o:["O tempo não comunica nada","A forma como gerimos o tempo — pontualidade, duração, silêncios — transmite mensagens sobre respeito, prioridades e status","Apenas em contextos formais","Apenas em culturas ocidentais"],a:1,e:"A 'cronémica' estuda o tempo como comunicação — chegar tarde comunica desrespeito; o tempo que dedicamos a alguém comunica a sua importância para nós."},
  {q:"O que é a 'distância íntima' na proxémica?",o:["Distância entre países","Zona reservada para relações íntimas (~0-45cm) onde a comunicação é muito pessoal e envolve toque","Distância entre colegas de trabalho","Distância em palcos públicos"],a:1,e:"A distância íntima (~0-45cm) é a zona mais privada, reservada para relações muito próximas — permite toque, sussurros e comunicação muito pessoal."},
  {q:"O que são 'microexpressões' faciais?",o:["Expressões muito exageradas","Expressões emocionais faciais brevíssimas (menos de 0.5 segundos) que revelam emoções genuínas","Expressões teatrais","Expressões aprendidas culturalmente"],a:1,e:"As microexpressões são flashes emocionais faciais involuntários — duram menos de 0.5 segundos e revelam emoções genuínas que tentamos esconder."},
  {q:"O que é o 'ruído semântico' na comunicação?",o:["Barulho físico no ambiente","Interferência causada por diferenças no significado atribuído às palavras entre interlocutores","Ruído em chamadas telefónicas","Erros de gramática"],a:1,e:"O ruído semântico surge quando emissor e receptor atribuem significados diferentes às mesmas palavras — criando mal-entendidos apesar da transmissão técnica ser perfeita."},
  {q:"Como a assertividade contribui para a resolução de conflitos?",o:["Elimina todos os conflitos","Permite expressar perspetivas diretamente e ouvir as do outro, criando condições para soluções mutuamente satisfatórias","Determina quem ganha o conflito","Evita que os conflitos sejam discutidos"],a:1,e:"A assertividade cria condições para resolver conflitos construtivamente — permite expressar as próprias necessidades claramente e ouvir as do outro, procurando soluções 'eu venço, tu também venço'."},
  {q:"Qual é o papel da 'empatia' na escuta ativa?",o:["A empatia não está relacionada com a escuta","A empatia permite compreender a perspetiva emocional do outro, tornando a escuta mais profunda e a resposta mais adequada","A empatia apenas serve para simpatizar","A empatia distorce a escuta objetiva"],a:1,e:"A empatia é central na escuta ativa — permite ir além das palavras e compreender os sentimentos e necessidades do outro, respondendo de forma mais eficaz."},
  {q:"O que é a 'metacomunicação'?",o:["Comunicação sobre comunicação","Comunicar sobre a própria comunicação — reflexão explícita sobre o processo comunicativo em curso","Comunicação através de metáforas","Comunicação de massas"],a:1,e:"A metacomunicação é comunicar sobre o próprio processo de comunicação — 'Acho que não me estou a fazer entender' é metacomunicação, uma forma de regular a interação."},
  {q:"O que são 'barreiras tecnológicas' à comunicação?",o:["Falta de interesse em tecnologia","Interferências causadas por tecnologia: falhas de ligação, notificações, desumanização das interações digitais, perda de sinais não-verbais","Excesso de tecnologia avançada","Apenas problemas de hardware"],a:1,e:"As barreiras tecnológicas incluem falhas de ligação, ausência de sinais não-verbais em comunicação digital, distrações de notificações e a desumanização de algumas formas de comunicação mediada."},
  {q:"Qual é a diferença entre 'simpatia' e 'empatia'?",o:["Não há diferença real","Simpatia é sentir compaixão por alguém; empatia é colocar-se no lugar do outro e compreender a sua perspetiva emocional","Empatia é mais superficial","Simpatia requer mais esforço"],a:1,e:"Simpatia é reconhecer o sofrimento do outro de fora. Empatia é entrar na perspetiva do outro — compreender como se sente a partir de dentro, sem julgamento."},
  {q:"Que papel desempenha o 'contexto' na comunicação interpessoal?",o:["O contexto não afeta a comunicação","O contexto (físico, social, cultural, temporal) molda o significado das mensagens e as expectativas dos interlocutores","O contexto só importa em negócios","O contexto apenas afeta a língua usada"],a:1,e:"O contexto é fundamental — uma mesma mensagem tem significados diferentes conforme o contexto físico, social, cultural e temporal em que é produzida."},
  {q:"O que é a 'Teoria dos Papéis' nas relações interpessoais?",o:["Teoria teatral","Conceito de que nas relações todos desempenhamos 'papéis' sociais com expectativas de comportamento associadas","Teoria de gestão empresarial","Teoria sobre papéis de género"],a:1,e:"A Teoria dos Papéis afirma que nas interações sociais desempenhamos papéis com comportamentos esperados — pai, aluno, líder — e que a violação desses papéis cria conflito."},
  {q:"O que significa 'maximizar resultados' na Troca Social?",o:["Ganhar sempre mais dinheiro","Tentar obter o máximo benefício das interações, às vezes mas nem sempre em prejuízo dos outros","Trabalhar o máximo de horas","Maximizar o número de relações"],a:1,e:"Na Troca Social, as pessoas tendem a maximizar resultados — procurar o máximo benefício. Mas cooperar pode ser estrategicamente mais vantajoso do que competir."},
  {q:"Como a IE contribui para a liderança eficaz?",o:["A IE é irrelevante para a liderança","Líderes com alta IE motivam melhor, gerem conflitos com mais eficácia, criam equipas mais coesas e inspiram confiança","A IE diminui a autoridade do líder","Apenas a inteligência cognitiva importa na liderança"],a:1,e:"A investigação mostra que a IE é um preditor-chave do sucesso na liderança — líderes emocionalmente inteligentes criam climas positivos, motivam equipas e gerem conflitos construtivamente."},
  {q:"O que é o 'princípio da cooperação' de Grice?",o:["Cooperar em todas as decisões","Princípio de que os interlocutores cooperam implicitamente para tornar a comunicação eficaz — sendo relevantes, verdadeiros e claros","Acordo contratual de cooperação","Cooperação em jogos"],a:1,e:"Grice propôs que a comunicação eficaz se baseia numa cooperação implícita — ser tão informativo quanto necessário, verdadeiro, relevante e claro (máximas de Grice)."},
  {q:"Que comportamento verbal caracteriza o comunicador passivo?",o:["Usa linguagem direta e clara","Usa termos hesitantes ('talvez', 'não sei bem'), dá respostas longas com pedidos de desculpa, cede facilmente","Usa ameaças implícitas","Usa sarcasmo frequente"],a:1,e:"O comunicador passivo hesita antes de responder, usa muitas qualificações ('talvez', 'acha que sim?'), pede muitas desculpas e cede facilmente quando desafiado."},
  {q:"Qual é o papel das 'normas de comunicação' nas relações?",o:["São apenas leis formais","Regras implícitas ou explícitas aceites pelos interlocutores que regulam quem fala, como, quando e sobre o quê","São apenas relevantes em contextos profissionais","Normas que nunca mudam"],a:1,e:"As normas de comunicação são regras implícitas ou explícitas que estruturam as interações — quem fala, em que ordem, que tópicos são adequados, como se exprime discordância."},
  {q:"O que é a 'autoconsciência' como primeiro pilar da IE de Goleman e por que razão é considerada a base de todos os outros?",o:["É a capacidade de estar atento ao ambiente externo","É a capacidade de reconhecer as próprias emoções no momento em que ocorrem e compreender como afetam pensamentos e comportamento — base de todos os outros pilares","É a consciência das emoções dos outros","É exclusivamente a capacidade de introspecção filosófica"],a:1,e:"A autoconsciência é o ponto de partida da IE: sem reconhecer as nossas próprias emoções em tempo real, não podemos regulá-las (autorregulação), nem motivarmo-nos genuinamente, nem ser empáticos. É a fundação de todos os outros pilares."},
  {q:"De que forma a 'Teoria dos Objetivos Múltiplos' explica conflitos aparentemente triviais nas relações interpessoais?",o:["Diz que os conflitos surgem sempre por razões financeiras","Mostra que quando os objetivos instrumentais, relacionais e identitários de duas pessoas entram em colisão, mesmo uma conversa simples pode escalar para conflito","Afirma que os conflitos são sempre intencionais","Explica que conflitos só surgem em comunicação verbal"],a:1,e:"A Teoria dos Objetivos Múltiplos revela que em cada interação perseguimos objetivos simultâneos — obter um resultado (instrumental), preservar a relação (relacional) e proteger a nossa imagem (identitário). Quando estes objetivos colidem com os do outro, surgem conflitos mesmo em situações aparentemente simples."},
  {q:"O que é a 'identificação' na retórica de Kenneth Burke?",o:["Identificar o público-alvo","Processo de estabelecer pontos de ligação e semelhança com o público para tornar a persuasão mais eficaz","Identificar argumentos falaciosos","Identificar a intenção do orador"],a:1,e:"Burke propôs que a persuasão eficaz começa com 'identificação' — o orador estabelece pontos de ligação e semelhança com o público, reduzindo a distância e aumentando a recetividade."},
  {q:"O que é a 'dissonância cognitiva' na comunicação interpessoal?",o:["Ruído cognitivo","Desconforto psicológico causado por informações contraditórias que o receptor tenta resolver — pode levar à rejeição de mensagens","Excesso de informação","Conflito de opiniões"],a:1,e:"A dissonância cognitiva é o desconforto de ter crenças contraditórias — ao comunicar, as pessoas frequentemente rejeitam informação que contradiz as suas crenças para reduzir esse desconforto."},
  {q:"Qual é a relação entre 'perceção' e 'comunicação'?",o:["A perceção não afeta a comunicação","A perceção filtro a realidade — vemos e ouvimos o que esperamos, o que afeta como interpretamos as mensagens dos outros","A perceção é objetiva","A perceção só afeta a comunicação escrita"],a:1,e:"A perceção é o filtro pelo qual interpretamos as mensagens — as nossas expectativas, experiências e estado emocional moldam o que 'vemos' e 'ouvimos' nas interações."},
  {q:"O que significa 'comunicar eficazmente' na prática?",o:["Falar muito e rapidamente","Conseguir que a mensagem pretendida seja recebida e compreendida como pretendido, produzindo o efeito desejado na relação","Usar vocabulário elaborado","Nunca criar conflito"],a:1,e:"A comunicação eficaz ocorre quando a mensagem intencionada é recebida e compreendida como pretendido — considerando o contexto, o receptor e a relação."},
  {q:"Qual é o problema da 'comunicação unilateral'?",o:["É muito eficiente","Ignora o feedback do receptor, não permite ajuste da mensagem e prejudica a relação interpessoal","É o método mais eficaz","Apenas funciona em contextos formais"],a:1,e:"A comunicação unilateral (sem feedback) não permite verificar se a mensagem foi compreendida, não cria diálogo e prejudica as relações interpessoais pela falta de reciprocidade."},
  {q:"Que papel tem a 'motivação' na gestão da informação (TGIM)?",o:["A motivação não tem papel","A motivação determina que tipo de informação as pessoas procuram para gerir a incerteza e a ansiedade em interações","Apenas motiva a comunicar mais","Motiva a evitar comunicação"],a:1,e:"Na TGIM, a motivação determina como as pessoas gerem a incerteza — dependendo do nível de ansiedade e incerteza, podem procurar ou evitar informação para regular o seu estado."},
  {q:"O que distingue a comunicação 'pública' da 'interpessoal'?",o:["Apenas o número de pessoas","A comunicação pública é unidirecional e formal; a interpessoal é bidirecional, pessoal e baseada em relação","A comunicação pública usa microfones","A interpessoal é apenas cara-a-cara"],a:1,e:"A comunicação interpessoal é íntima, bidirecional e moldada pela relação — ao contrário da pública, que é mais formal, unidirecional e não depende de relação pessoal."},
  {q:"O que é a 'gestão de impressões' na comunicação?",o:["Gerir a reputação empresarial","O processo pelo qual as pessoas controlam conscientemente a informação que transmitem para influenciar como são percebidas pelos outros","Impressão de documentos","Gestão de fotografias"],a:1,e:"A gestão de impressões (Goffman) é o processo pelo qual gerimos a nossa 'apresentação' para controlar como os outros nos percebem — escolhendo roupa, palavras, postura."},
  {q:"O que é a 'janela de Johari'?",o:["Um tipo de janela arquitetónica","Modelo que representa os níveis de autoconhecimento e comunicação: o que é conhecido/desconhecido por si mesmo e pelos outros","Um modelo de negociação","Um modelo de gestão de conflitos"],a:1,e:"A Janela de Johari divide o autoconhecimento em 4 quadrantes: Arena (conhecido por mim e pelos outros), Ponto Cego (desconhecido por mim, conhecido pelos outros), Fachada (conhecido por mim, desconhecido pelos outros) e Desconhecido."},
  {q:"Como os 'desafios digitais' afetam a autenticidade comunicativa?",o:["A tecnologia não afeta a autenticidade","A comunicação digital facilita a curadoria e performance da identidade, podendo criar distância entre a persona apresentada e o eu autêntico","A tecnologia sempre aumenta a autenticidade","A autenticidade é mais fácil online"],a:1,e:"As redes sociais e comunicação digital permitem construir personas cuidadosamente editadas — criando tensão entre a 'performance' online e a autenticidade das relações interpessoais reais."},
  {q:"O que é a 'comunicação não-violenta' (CNV)?",o:["Comunicar sem usar palavras fortes","Abordagem de comunicação focada em observações, sentimentos, necessidades e pedidos concretos — sem julgamentos ou críticas pessoais","Comunicar em voz baixa","Evitar toda a forma de conflito"],a:1,e:"A CNV (Rosenberg) propõe comunicar através de: Observações (não julgamentos), Sentimentos, Necessidades e Pedidos concretos — criando ligação genuína sem violência verbal."},
  {q:"Qual é a relação entre 'locus de controlo' e comunicação assertiva?",o:["Não há relação","Pessoas com locus de controlo interno (creem que controlam os seus resultados) tendem a ser mais assertivas e eficazes comunicativamente","Locus externo facilita assertividade","O locus de controlo é irrelevante"],a:1,e:"O locus de controlo interno — a crença de que controlamos os nossos resultados — está associado a maior assertividade, pois a pessoa acredita que a sua comunicação pode fazer diferença."},
  {q:"O que é a 'competência comunicativa'?",o:["Apenas ter boas notas em língua portuguesa","A capacidade de comunicar de forma eficaz e adequada em diferentes contextos, relações e situações culturais","Falar muitas línguas","Ter vocabulário extenso"],a:1,e:"A competência comunicativa é a capacidade de comunicar eficazmente e adequadamente — saber o que dizer, como dizer, a quem, quando e em que contexto cultural e relacional."}
];

