// DATA: 50 FLASHCARDS
// ============================================================
const flashData = [
  {cat:"Glossário",t:"Comunicação Interpessoal",d:"Troca de informação, significado e emoções entre duas ou mais pessoas numa relação. É inseparável das relações humanas (Minter, 2010)."},
  {cat:"Glossário",t:"Sinais Não-Verbais",d:"Mensagens comunicadas sem palavras: gestos, expressões faciais, postura, toque, tom de voz e uso do espaço."},
  {cat:"Glossário",t:"TGIM — Teoria da Gestão da Informação Motivada",d:"Explica como as pessoas gerem a incerteza e ansiedade em situações de comunicação, procurando ou evitando informação."},
  {cat:"Glossário",t:"Teoria dos Objetivos Múltiplos",d:"Ao comunicar, perseguimos vários objetivos em simultâneo: instrumentais (obter algo), relacionais (manter a relação) e identitários (proteger a imagem)."},
  {cat:"Glossário",t:"Perfil Verbal-Não Verbal Discrepante",d:"Situação em que a mensagem verbal e a não-verbal são inconsistentes — o que se diz contradiz o que o corpo expressa."},
  {cat:"Glossário",t:"Troca Social",d:"Princípio de que as interações humanas envolvem trocas de recursos, custos e recompensas, orientadas pelo interesse próprio e reciprocidade."},
  {cat:"Glossário",t:"Interacionismo Simbólico",d:"Perspetiva que vê o comportamento social como resultado dos significados simbólicos que as pessoas constroem e partilham nas interações."},
  {cat:"Glossário",t:"Teorema de Thomas",d:"'Se as pessoas definem as situações como reais, elas são reais nas suas consequências' — o poder das perceções na comunicação."},
  {cat:"Glossário",t:"Escuta Ativa",d:"Forma de escuta em que o receptor demonstra atenção plena, compreensão e interesse ativo — fazendo perguntas, dando feedback, parafraseando."},
  {cat:"Glossário",t:"Escuta Empática",d:"Escuta que procura compreender os sentimentos e perspetiva emocional do outro, colocando-se no seu lugar sem julgamento."},
  {cat:"Glossário",t:"Escuta Reflexiva",d:"Técnica de escuta em que se reformula o que o outro disse — 'Então o que estás a dizer é...' — para confirmar compreensão."},
  {cat:"Glossário",t:"Barreiras Psicológicas",d:"Obstáculos à comunicação causados por preconceitos, emoções fortes, expectativas ou experiências passadas que distorcem a receção da mensagem."},
  {cat:"Glossário",t:"Barreiras Semânticas",d:"Interferências causadas por diferenças no significado atribuído às palavras ou símbolos entre emissor e recetor."},
  {cat:"Glossário",t:"Inteligência Emocional (IE)",d:"Capacidade de reconhecer, compreender e gerir as próprias emoções e as dos outros. Inclui: autoconsciência, autorregulação, motivação, empatia e competências sociais."},
  {cat:"Glossário",t:"IE de Habilidade (Ability)",d:"Conjunto de capacidades cognitivas: perceber, usar, compreender e regular emoções. Permite ler emoções nos outros com precisão."},
  {cat:"Glossário",t:"IE de Traço (Trait)",d:"Traços auto-reportados relacionados com autoeficácia emocional, bem-estar subjetivo e sociabilidade — como a pessoa percebe as suas características emocionais."},
  {cat:"Glossário",t:"IE Mista (Competências)",d:"Competências comportamentais observáveis: dar feedback, gerir conflitos, demonstrar empatia — aplicadas ao desempenho social e profissional."},
  {cat:"Glossário",t:"5 Pilares da IE (Goleman)",d:"Autoconsciência · Autorregulação · Motivação intrínseca · Empatia · Competências Sociais"},
  {cat:"Glossário",t:"Teoria da Atribuição",d:"Processo pelo qual interpretamos as causas do comportamento dos outros — atribuindo causas internas (personalidade) ou externas (situação)."},
  {cat:"Glossário",t:"Teoria da Troca Afetiva",d:"Explica como as emoções trocadas nas interações influenciam e regulam a qualidade das relações interpessoais."},
  {cat:"Glossário",t:"Estilo Assertivo",d:"'Eu venço, tu também venças.' Expressa necessidades com respeito pelos direitos próprios e alheios. Voz firme, contacto visual sem intimidar, expressão aberta."},
  {cat:"Glossário",t:"Estilo Passivo",d:"'Eu perco, tu ganhas.' Evita conflito, sublima necessidades, cede facilmente. Voz fraca, olhar desviado, hesitação constante."},
  {cat:"Glossário",t:"Estilo Agressivo",d:"'Eu venço, tu perdes.' Impõe necessidades atacando os outros. Ameaças, sarcasmo, olhar desafiante, gestos ameaçadores."},
  {cat:"Glossário",t:"Estilo Passivo-Agressivo",d:"Evita confronto direto mas manifesta insatisfação indiretamente: ironia, sabotagem velada, ambiguidades e resistência passiva."},
  {cat:"Glossário",t:"Modelo DESC",d:"Estrutura assertiva: Descreve o comportamento → Expressa sentimentos → Sugere mudança → Consequências positivas."},
  {cat:"Glossário",t:"Modelo XYZ",d:"'Quando fazes X, sinto Y, porque Z.' Expressa sentimentos sem acusar a pessoa, focando no comportamento específico."},
  {cat:"Glossário",t:"Teoria da Retórica Normativa (TRN)",d:"Combina os princípios clássicos de Aristóteles com ética comunicativa — como persuadir de forma eficaz, honesta e respeitosa."},
  {cat:"Glossário",t:"Ethos",d:"Credibilidade e integridade do comunicador. Pilar da persuasão: o público confia mais em quem percebe como competente e honesto."},
  {cat:"Glossário",t:"Logos",d:"Apelo à razão. Uso de argumentos lógicos, dados e evidências para convencer — o lado racional da persuasão."},
  {cat:"Glossário",t:"Pathos",d:"Apelo emocional. Ativar emoções do público (esperança, medo, empatia) para tornar a mensagem mais persuasiva — deve ser usado eticamente."},
  {cat:"Glossário",t:"Proxémica",d:"Estudo do uso do espaço físico nas interações. Zonas: íntima (~0-45cm), pessoal (~120cm), social (~360cm), pública (+360cm). (Hall)"},
  {cat:"Glossário",t:"Cinésica",d:"Estudo dos movimentos corporais como comunicação: gestos, postura, expressões faciais, contacto visual, orientação do corpo. (Birdwhistell)"},
  {cat:"Glossário",t:"Paralinguagem",d:"Elementos vocais que acompanham as palavras: tom, ritmo, volume, pausas, entonação, timbre — modificam o significado das mensagens."},
  {cat:"Glossário",t:"Metacomunicação",d:"Comunicar sobre o próprio processo de comunicação — 'Acho que não nos estamos a entender' é metacomunicação."},
  {cat:"Glossário",t:"Dissonância Cognitiva",d:"Desconforto psicológico causado por crenças contraditórias. Na comunicação, pode levar à rejeição de mensagens que contradizem crenças existentes."},
  {cat:"Glossário",t:"Janela de Johari",d:"Modelo com 4 quadrantes: Arena (conhecido por mim e outros), Ponto Cego (outros sabem, eu não), Fachada (eu sei, outros não), Desconhecido."},
  {cat:"Glossário",t:"Gestão de Impressões",d:"Processo pelo qual controlamos a informação que transmitimos para influenciar como somos percebidos pelos outros (Goffman)."},
  {cat:"Glossário",t:"Interdependência",d:"Nas relações, os resultados de cada pessoa são influenciados pelos esforços dos outros — o sucesso individual depende do parceiro."},
  {cat:"Glossário",t:"Reciprocidade",d:"Princípio de que as trocas nas relações devem ter retorno — quando alguém nos dá algo, sentimos necessidade de retribuir."},
  {cat:"Glossário",t:"Microexpressões",d:"Expressões faciais brevíssimas (menos de 0.5 segundos) que revelam emoções genuínas — difíceis de falsificar ou esconder."},
  {cat:"Glossário",t:"Competência Comunicativa",d:"Capacidade de comunicar de forma eficaz e adequada em diferentes contextos, relações e situações culturais."},
  {cat:"Glossário",t:"Comunicação Não-Violenta (CNV)",d:"Abordagem (Rosenberg): Observações → Sentimentos → Necessidades → Pedidos. Sem julgamentos ou críticas pessoais."},
  {cat:"Glossário",t:"Comunicação de Alto Contexto",d:"Estilo cultural onde muito do significado está no contexto implícito, nas relações e na comunicação não-verbal (ex: cultura japonesa)."},
  {cat:"Glossário",t:"Comunicação de Baixo Contexto",d:"Estilo cultural onde a mensagem é explícita e direta — a maioria do significado está nas palavras ditas (ex: cultura americana)."},
  {cat:"Glossário",t:"Princípio da Cooperação (Grice)",d:"Na comunicação eficaz, os interlocutores cooperam implicitamente: sendo informativos, verdadeiros, relevantes e claros (Máximas de Grice)."},
  {cat:"Glossário",t:"Ruído Semântico",d:"Interferência causada por diferenças no significado atribuído às palavras — mesmo com transmissão perfeita, há mal-entendido."},
  {cat:"Glossário",t:"Locus de Controlo Interno",d:"Crença de que controlamos os nossos resultados — associado a maior assertividade e eficácia comunicativa."},
  {cat:"Glossário",t:"Barreiras Tecnológicas",d:"Interferências na comunicação digital: falhas de ligação, ausência de sinais não-verbais, distrações de notificações, desumanização."},
  {cat:"Glossário",t:"Simbolismo",d:"No interacionismo simbólico, os símbolos (palavras, gestos, objetos) têm significados socialmente partilhados que medeiam todas as interações."},
  {cat:"Glossário",t:"Autenticidade Comunicativa",d:"Correspondência genuína entre o que se sente interiormente e o que se expressa — comunicar sem máscaras ou performatividade excessiva."}
];

